13.  * See the License for the specific language governing permissions and
14.  * limitations under the License.
15.  */
16. package nl.talsmasoftware.umldoclet.javadoc;
17. 
18. import jdk.javadoc.doclet.Doclet;
19. import jdk.javadoc.doclet.Doclet.Option.Kind;
20. import net.sourceforge.plantuml.OptionFlags;
21. import nl.talsmasoftware.umldoclet.UMLDoclet;
22. 
23. import java.util.Arrays;
24. import java.util.LinkedHashSet;
25. import java.util.List;
26. import java.util.MissingResourceException;
27. import java.util.Optional;
28. import java.util.ResourceBundle;
29. import java.util.Set;
30. import java.util.TreeSet;
31. import java.util.function.Consumer;
32. import java.util.stream.Stream;
33. 
34. import static java.util.Collections.emptyList;
35. import static java.util.Comparator.comparing;
36. import static java.util.Locale.ENGLISH;
37. import static java.util.Objects.requireNonNull;
38. import static java.util.stream.Collectors.toList;
39. 
40. /**
41.  * Type that serves as an 'anti-corruption' facade between our Doclet
42.  * and the {@code internal} configuration of the StandardDoclet.
43.  * <p>
44.  * Although we want to apply the standard configuration options that make
45.  * sense to the UML doclet, we don't want to re-implement all standard options.
46.  * <p>
47.  * However, we also don't want to have the UML Doclet blow up in our
48.  * face at runtime when the standard configuration implementation changes.
49.  *
50.  * @author Sjoerd Talsma
51.  */
52. final class UMLOptions {
53.     private final DocletConfig config;
54.     private final Set<Doclet.Option> standardOptions;
55.     private final Set<Doclet.Option> options;
56. 
57.     UMLOptions(DocletConfig config) {
58.         this(config, null);
59.     }
60. 
61.     private UMLOptions(DocletConfig config, Set<? extends Doclet.Option> standardOptions) {
62.         this.config = requireNonNull(config, "Configuration is <null>.");
63.         this.standardOptions = standardOptions == null ? null : new LinkedHashSet<>(standardOptions);
64.         this.options = new TreeSet<>(comparing(o -> o.getNames().get(0), String::compareTo));
65. 
66.         // Options from Standard doclet that we also support
67.         this.options.add(new Option("-quiet", 0, Kind.OTHER, args -> config.quiet = true));
68.         this.options.add(new Option("-verbose", 0, Kind.OTHER, args -> config.verbose = true));
69.         this.options.add(new Option("-docencoding", 1, Kind.OTHER, args -> config.docencoding = args.get(0)));
70.         this.options.add(new Option("-encoding", 1, Kind.OTHER, args -> config.encoding = args.get(0)));
71.         this.options.add(new Option("-link", 1, Kind.OTHER,
72.                 args -> config.externalLinks.add(new ExternalLink(config, args.get(0), args.get(0)))));
73.         this.options.add(new Option("-linkoffline", 2, Kind.OTHER,
74.                 args -> config.externalLinks.add(new ExternalLink(config, args.get(0), args.get(1)))));
75.         this.options.add(new Option("-private", 0, Kind.OTHER, args -> config.showMembers("private")));
76.         this.options.add(new Option("-package", 0, Kind.OTHER, args -> config.showMembers("package")));
77.         this.options.add(new Option("-protected", 0, Kind.OTHER, args -> config.showMembers("protected")));
78.         this.options.add(new Option("-public", 0, Kind.OTHER, args -> config.showMembers("public")));
79.         this.options.add(new Option("--show-members", 1, Kind.OTHER, args -> config.showMembers(args.get(0))));
80.         this.options.add(new Option("-d", 1, Kind.OTHER, args -> config.destDirName = args.get(0)));
81. 
82.         // Our own options
83.         this.options.add(new Option("--plantuml-server-url -plantumlServerUrl", 1, Kind.STANDARD,
84.                 args -> config.plantumlServerUrl = args.get(0)));
85.         this.options.add(new Option("--delegate-doclet -delegateDoclet", 1, Kind.STANDARD,
86.                 args -> config.delegateDoclet = args.get(0)));
87.         this.options.add(new Option("--create-puml-files -createPumlFiles", 0, Kind.STANDARD, args -> config.renderPumlFile = true));
88.         this.options.add(new Option("--uml-image-directory -umlImageDirectory", 1, Kind.STANDARD, args -> config.images.directory = args.get(0)));
89.         this.options.add(new Option("--uml-image-format -umlImageFormat", 1, Kind.STANDARD, args -> config.images.addImageFormat(args.get(0))));
90.         this.options.add(new Option("--uml-encoding -umlEncoding", 1, Kind.STANDARD, args -> config.umlencoding = args.get(0)));
91.         this.options.add(new Option("--uml-excluded-type-references -umlExcludedTypeReferences", 1, Kind.STANDARD,
92.                 args -> config.excludedReferences = splitToList(args.get(0))));
93.         this.options.add(new Option("--uml-excluded-package-dependencies -umlExcludedPackageDependencies", 1, Kind.STANDARD,
94.                 args -> config.excludedPackageDependencies = splitToList(args.get(0))));
95.         this.options.add(new Option("--uml-custom-directive -umlCustomDirective", 1, Kind.STANDARD,
96.                 args -> config.customPlantumlDirectives.add(args.get(0))));
97.         this.options.add(new Option("--fail-on-cyclic-package-dependencies -failOnCyclicPackageDependencies", 1, Kind.STANDARD,
98.                 args -> config.failOnCyclicPackageDependencies = asBoolean(args.get(0))));
99.         this.options.add(new Option("--uml-java-bean-properties-as-fields -umlJavaBeanPropertiesAsFields", 0, Kind.STANDARD,
100.                 args -> config.methodConfig.javaBeanPropertiesAsFields = true));
101.         this.options.add(new Option("--uml-timeout -umlTimeout", 1, Kind.STANDARD, this::setTimeout));
102.     }
103. 
104.     Set<Doclet.Option> mergeWith(final Set<? extends Doclet.Option> standardOptions) {
105.         if (standardOptions == null || standardOptions.isEmpty()) return this.options;
106.         Set<Doclet.Option> copy = new UMLOptions(config, standardOptions).options;
107.         copy.addAll(standardOptions);
108.         return copy;
109.     }
110. 
111.     /**
112.      * Split a value on comma and semicolon ({@code ','} and {@code ';'}) and trim each value,
113.      * then collect each non-empty value into a list.
114.      *
115.      * @param value The value to split into a list.
116.      * @return The split value as a list.
117.      */
118.     private static List<String> splitToList(String value) {
119.         return value == null || value.isEmpty() ? emptyList()
120.                 : Stream.of(value.split("[,;]")).map(String::trim).filter(s -> !s.isEmpty()).collect(toList());
121.     }
122. 
123.     private static boolean asBoolean(String value) {
124.         return "true".equalsIgnoreCase(value);
125.     }
126. 
127.     private void setTimeout(List<String> timeout) {
128.         try {
129.             int timeoutSeconds = Integer.parseInt(timeout.get(0));
130.             OptionFlags.getInstance().setTimeoutMs(1000L * timeoutSeconds);
131.         } catch (RuntimeException rte) {
132.             throw new IllegalArgumentException("Unrecognized timeout value: seconds expected, received: " + timeout, rte);
133.         }
134.     }
135. 
136.     private class Option implements Doclet.Option {
137.         private static final String MISSING_KEY = "<MISSING KEY>";
138.         private final Consumer<List<String>> processor;
139.         private final String[] names;
140.         private final String parameters;
141.         private final String description;
142.         private final int argCount;
143.         private final Kind kind;
144. 
145.         protected Option(String name, int argCount, Kind kind, Consumer<List<String>> processor) {
146.             this.processor = processor;
147.             this.names = name.trim().split("\\s+");
148.             this.description = resourceMsg(names[0] + ".description");
149.             this.parameters = resourceMsg(names[0] + ".parameters");
150.             this.argCount = argCount;
151.             this.kind = kind;
152.         }
153. 
154.         private String resourceMsg(String key) {
155.             try {
156.                 String resourceKey = "doclet.usage." + key.toLowerCase(ENGLISH).replaceFirst("^-+", "");
157.                 return ResourceBundle.getBundle(UMLDoclet.class.getName()).getString(resourceKey);
158.             } catch (MissingResourceException mre) {
159.                 return MISSING_KEY;
160.             }
161.         }
162. 
163.         @Override
164.         public String getDescription() {
165.             return findDelegate().map(Doclet.Option::getDescription)
166.                     .filter(s -> !s.isEmpty() && !MISSING_KEY.equals(s))
167.                     .orElse(description);
168.         }
169. 
170.         @Override
171.         public Kind getKind() {
172.             return kind;
173.         }
174. 
175.         @Override
176.         public List<String> getNames() {
177.             return Arrays.asList(names);
178.         }
179. 
180.         @Override
181.         public String getParameters() {
182.             return parameters;
183.         }
184. 
185.         @Override
186.         public int getArgumentCount() {
187.             return argCount;
188.         }
189. 
190.         private boolean matches(Doclet.Option other) {
191.             List<String> otherNames = Optional.ofNullable(other).map(Doclet.Option::getNames).orElse(emptyList());
192.             return !otherNames.isEmpty() && names[0].equalsIgnoreCase(otherNames.get(0));
193.         }
194. 
195.         private Optional<Doclet.Option> findDelegate() {
196.             return Optional.ofNullable(standardOptions).flatMap(set -> set.stream().filter(this::matches).findFirst());
197.         }
198. 
199.         @Override
200.         public boolean process(String option, List<String> arguments) {
201.             processor.accept(arguments);
202.             return findDelegate().map(delegate -> delegate.process(option, arguments)).orElse(true);
203.         }
204. 
205.         @Override
206.         public String toString() {
207.             return Arrays.toString(names);
208.         }
209.     }
210. }
211.

