package net.sourceforge.plantuml;

import net.sourceforge.plantuml.cli.GlobalConfig;
import net.sourceforge.plantuml.cli.GlobalConfigKey;

/**
 * Bridge class to maintain compatibility with older PlantUML OptionFlags.
 */
public class OptionFlags {
    private static final OptionFlags singleton = new OptionFlags();

    public OptionFlags() {
    }

    public static OptionFlags getInstance() {
        return singleton;
    }

    public final void setVerbose(boolean verbose) {
        GlobalConfig.getInstance().put(GlobalConfigKey.VERBOSE, verbose);
    }

    public void setFileSeparator(String fileSeparator) {
        GlobalConfig.getInstance().put(GlobalConfigKey.FILE_SEPARATOR, fileSeparator);
    }

    public void setReplaceWhiteBackgroundByTransparent(boolean replace) {
        GlobalConfig.getInstance().put(GlobalConfigKey.REPLACE_WHITE_BACKGROUND_BY_TRANSPARENT, replace);
    }

    public final long getTimeoutMs() {
        Object val = GlobalConfig.getInstance().value(GlobalConfigKey.TIMEOUT_MS);
        if (val instanceof Long) {
            return (Long) val;
        }
        return 900000L;
    }

    public final void setTimeoutMs(long timeoutMs) {
        GlobalConfig.getInstance().put(GlobalConfigKey.TIMEOUT_MS, timeoutMs);
    }
}

